mapper.select:
select
carInfo.*,
proprietor.name
from car_info carInfo
left join proprietor proprietor on carInfo.user_id = proprietor.id

    and carInfo.id = #{id}
    and carInfo.car_img = #{carImg}
    and carInfo.user_id = #{userId}
    and carInfo.car_number = #{carNumber}
    and carInfo.vehicle = #{vehicle}
    and carInfo.create_time = #{createTime}
    and proprietor.name like concat('%',#{name},'%')


    limit #{current},#{pageSize}

select count(*) from car_info carInfo
left join proprietor proprietor on carInfo.user_id = proprietor.id

    and carInfo.id = #{id}
    and carInfo.car_img = #{carImg}
    and carInfo.user_id = #{userId}
    and carInfo.car_number = #{carNumber}
    and carInfo.vehicle = #{vehicle}
    and carInfo.create_time = #{createTime}
    and proprietor.name like concat('%',#{name},'%')
